import re

def word_count_ascii(s):
    words = re.findall(r'[A-Za-z]+', s)
    lower = [w.lower() for w in words]
    counts = {}
    for w in lower:
        counts[w] = counts.get(w, 0) + 1
    return sorted([[w, counts[w]] for w in counts], key=lambda x: x[0])

